export const JHARKHAND_QUERIES: JharkhandQueryItem[] = JHARKHAND_QUERIES_RAW.map(([id, query, category]) => ({
  id,
  query,
  category,
}));

export function getRandomQueries(count: number = 10): JharkhandQueryItem[] {
  const shuffled = [...JHARKHAND_QUERIES].sort(() => 0.5 - Math.random());
  return shuffled.slice(0, count);
}

export function getQueriesByCategory(category: string): JharkhandQueryItem[] {
  return JHARKHAND_QUERIES.filter((q) => q.category.toLowerCase() === category.toLowerCase());
}
